//! SPIKE (ADR 0015): the wasm boundary for two rules, written two ways so they can be measured
//! against each other — `serde-wasm-bindgen` (JS values in and out, types generated by `tsify`)
//! and JSON strings (`serde_json` on both sides of one `String`).
//!
//! The rules' own inputs (`PlanRow`) carry no `Deserialize`, by design: they are what persistence
//! gathers, not a wire shape. So the boundary has its own DTOs, as the Rust conformance tests do.

use serde::{Deserialize, Serialize};
use tsify::Tsify;
use wasm_bindgen::prelude::*;

use crate::scopes::key::ScopeKey;
use crate::tasks::model::{Status, TimeScope};
use crate::tasks::rules::gestures::{status_after, StatusRefusal, StatusStep};
use crate::tasks::rules::plan::{triage, PlanAncestor, PlanRow};

/// What a status gesture leaves, as the board's `StatusPrediction` spells it.
#[derive(Serialize, Tsify)]
#[serde(tag = "outcome", rename_all = "snake_case")]
pub enum StatusPrediction {
    /// The status it writes.
    Written {
        #[tsify(type = "{ kind: \"ordinary\" | \"agentic\"; status: string }")]
        status: Status,
    },
    /// Why it writes nothing.
    Refused {
        #[tsify(type = "\"compound\" | \"alt_enter_agentic_not_doing\"")]
        reason: StatusRefusal,
    },
}

fn predict(step: StatusStep, current: Status, compound: bool) -> StatusPrediction {
    match status_after(step, current, compound) {
        Ok(status) => StatusPrediction::Written { status },
        Err(reason) => StatusPrediction::Refused { reason },
    }
}

/// `tasks::rules::gestures::status_after`, through serde-wasm-bindgen. tsify only declares the
/// types: its `into_wasm_abi`/`from_wasm_abi` are deprecated (they leak, tsify#65).
#[wasm_bindgen(js_name = statusAfter, unchecked_return_type = "StatusPrediction")]
pub fn status_after_js(
    #[wasm_bindgen(unchecked_param_type = "\"advance\" | \"alt\"")] step: JsValue,
    #[wasm_bindgen(unchecked_param_type = "{ kind: \"ordinary\" | \"agentic\"; status: string }")]
    current: JsValue,
    compound: bool,
) -> Result<JsValue, JsError> {
    let step: StatusStep = serde_wasm_bindgen::from_value(step)?;
    let current: Status = serde_wasm_bindgen::from_value(current)?;
    Ok(predict(step, current, compound).serialize(&serde_wasm_bindgen::Serializer::json_compatible())?)
}

#[derive(Deserialize)]
struct GestureCall {
    step: StatusStep,
    current: Status,
    compound: bool,
}

/// The same, through one JSON string each way.
#[cfg(feature = "json")]
#[wasm_bindgen(js_name = statusAfterJson)]
pub fn status_after_json(call: &str) -> Result<String, JsError> {
    let call: GestureCall = serde_json::from_str(call)?;
    Ok(serde_json::to_string(&predict(call.step, call.current, call.compound))?)
}

/// One row a planning pass reads, in the corpus' (and the board's) camelCase.
#[derive(Deserialize, Tsify)]
#[serde(rename_all = "camelCase")]
pub struct TriageRow {
    id: String,
    #[serde(default, rename = "virtual")]
    drawing: bool,
    #[serde(default)]
    #[tsify(type = "TimeScopeWire | null", optional)]
    time_scope: Option<TimeScope>,
    #[serde(default)]
    #[tsify(type = "TimeScopeWire | null", optional)]
    plan: Option<TimeScope>,
    #[serde(default)]
    #[tsify(type = "TimeScopeWire | null", optional)]
    inherited_plan: Option<TimeScope>,
    #[serde(default)]
    #[tsify(optional)]
    empty_plan: bool,
    #[serde(default)]
    #[tsify(optional)]
    overdue: bool,
    #[serde(default)]
    #[tsify(type = "{ timeScope?: TimeScopeWire | null }[]", optional)]
    ancestors: Vec<TriageAncestor>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct TriageAncestor {
    #[serde(default)]
    time_scope: Option<TimeScope>,
}

/// A planning pass: the scope it plans into, that scope's parent, and the rows.
#[derive(Deserialize, Tsify)]
pub struct TriageCall {
    #[tsify(type = "ScopeKeyWire")]
    target: ScopeKey,
    #[tsify(type = "ScopeKeyWire | null")]
    parent: Option<ScopeKey>,
    rows: Vec<TriageRow>,
}

/// The three heaps, by row id.
#[derive(Serialize, Tsify)]
#[serde(rename_all = "camelCase")]
pub struct TriageIds {
    unplanned: Vec<String>,
    planned: Vec<String>,
    parent_planned: Vec<String>,
}

#[wasm_bindgen(typescript_custom_section)]
const WIRE_TYPES: &'static str = r#"
/** Hand-written in the spike; ADR 0015 generates these from the models. */
export type ScopeKeyWire = { kind: string; date?: string; part?: string; start?: string; end?: string };
export type TimeScopeWire = { start_id: ScopeKeyWire; end_id: ScopeKeyWire };
"#;

fn rows(call: &TriageCall) -> Vec<PlanRow> {
    call.rows
        .iter()
        .map(|row| PlanRow {
            id: row.id.clone(),
            stored: !row.drawing,
            time_scope: row.time_scope.clone(),
            plan: row.plan.clone(),
            inherited_plan: row.inherited_plan.clone(),
            empty_plan: row.empty_plan,
            overdue: row.overdue,
            ancestors: row
                .ancestors
                .iter()
                .map(|ancestor| PlanAncestor { time_scope: ancestor.time_scope.clone() })
                .collect(),
        })
        .collect()
}

fn run(call: &TriageCall) -> TriageIds {
    let rows = rows(call);
    let panes = triage(&rows, call.target.bounds(), call.parent.as_ref());
    let ids = |heap: Vec<&PlanRow>| heap.into_iter().map(|row| row.id.clone()).collect();
    TriageIds {
        unplanned: ids(panes.unplanned),
        planned: ids(panes.planned),
        parent_planned: ids(panes.parent_planned),
    }
}

/// `tasks::rules::plan::triage`, through serde-wasm-bindgen.
#[cfg(feature = "plan")]
#[wasm_bindgen(js_name = planTriage, unchecked_return_type = "TriageIds")]
pub fn plan_triage_js(
    #[wasm_bindgen(unchecked_param_type = "TriageCall")] call: JsValue,
) -> Result<JsValue, JsError> {
    let call: TriageCall = serde_wasm_bindgen::from_value(call)?;
    let ids = run(&call);
    Ok(ids.serialize(&serde_wasm_bindgen::Serializer::json_compatible())?)
}

/// The same, through one JSON string each way.
#[cfg(all(feature = "json", feature = "plan"))]
#[wasm_bindgen(js_name = planTriageJson)]
pub fn plan_triage_json(call: &str) -> Result<String, JsError> {
    let call: TriageCall = serde_json::from_str(call)?;
    Ok(serde_json::to_string(&run(&call))?)
}
